package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@PathVariable("personId") String personId, @Val Sheet sheet,
            PersonRepository repository, Out<Person> personOut) throws PersonNotFoundException {
        Person person = null;
        try {
            person = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: not found
        }
        if (person == null) throw new PersonNotFoundException(personId);
        personOut.set(person);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;

public class SavePerson {
    public void save(@Val Person person, PersonRepository repository) throws StalePersonException {
        if (!repository.save(person)) throw new StalePersonException(String.valueOf(person.getId()));
    }
}
package net.officefloor.hq.app.role;

import jakarta.servlet.http.HttpServletRequest;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetArchivedException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.web.bind.annotation.PathVariable;

/**
 * Refuses any change by a viewer, and any change at all on an archived sheet, before anything is
 * read or written. A viewer sees every screen and figure and can change nothing; an archived sheet
 * stays visible to everyone and no one can change it. Runs first on every change endpoint except the
 * bulk ones, which go through with every selected item refused.
 */
public class CheckCanChange {
    public void check(@PathVariable("sheetId") String sheetId, RoleRepository roles, SheetRepository sheets,
            HttpServletRequest request) throws ViewerException, SheetArchivedException {
        String id = sheetId == null ? "" : sheetId.trim();
        String user = Audit.user(request);
        if (Role.VIEWER.equals(roles.roleOf(id, user))) {
            throw new ViewerException("A viewer may not change the sheet");
        }
        if (sheets.isArchived(id)) throw new SheetArchivedException(id);
    }
}
package net.officefloor.hq.app.person;

/** Whether an edit changed the person's own terms from those the row showed before the save. */
public record TermsEdit(boolean changed) {}
package net.officefloor.hq.app.person;

/** Whether an edit changed the person's contact from the one stored before the save. */
public record ContactEdit(boolean changed) {}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Sheet sheet, @Val Person person, PersonRepository people, SheetRepository sheets,
            ObjectResponse<PersonResponse> response) {
        boolean clashing = PersonRepository.clashes(person, people.namesIn(sheets.tree(sheet.id())));
        response.send(PersonResponse.from(person, sheet.today(), clashing));
    }
}

